RRB.load({"id": "ntpc-full-9", "exam": "ntpc", "label": "NTPC UG full mock 9 (100 Q)", "questions": [{"s": "General Awareness", "t": "Economy", "q": "A situation of high inflation together with economic stagnation and high unemployment is called:", "o": ["Stagflation", "Deflation", "Disinflation", "Reflation"], "a": 0, "e": "Stagflation combines rising prices with slow growth, as seen in the 1970s oil crisis.", "qh": "ऊँची महँगाई के साथ आर्थिक ठहराव और ऊँची बेरोज़गारी वाली स्थिति को क्या कहते हैं?", "oh": ["मुद्रास्फीतिजनित मंदी (स्टैगफ़्लेशन)", "अपस्फीति (डिफ़्लेशन)", "अवस्फीति (डिसइन्फ़्लेशन)", "पुनःस्फीति (रिफ़्लेशन)"], "eh": "स्टैगफ़्लेशन में बढ़ती कीमतें और धीमी वृद्धि साथ होती हैं, जैसे 1970 के दशक के तेल संकट में।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "The Union Budget is called the 'Annual Financial Statement' under which Article?", "o": ["Article 110", "Article 117", "Article 112", "Article 280"], "a": 2, "e": "Article 112 requires the President to lay the Annual Financial Statement before Parliament each year.", "qh": "केंद्रीय बजट को किस अनुच्छेद के तहत 'वार्षिक वित्तीय विवरण' कहा जाता है?", "oh": ["अनुच्छेद 110", "अनुच्छेद 117", "अनुच्छेद 112", "अनुच्छेद 280"], "eh": "अनुच्छेद 112 के तहत राष्ट्रपति हर साल संसद के सामने वार्षिक वित्तीय विवरण रखवाते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Neyveli in Tamil Nadu is known for large deposits of:", "o": ["Lignite", "Iron ore", "Bauxite", "Mica"], "a": 0, "e": "Neyveli (Cuddalore district) has India's largest lignite mines, run by NLC India.", "qh": "तमिलनाडु का नेवेली किसके बड़े भंडार के लिए जाना जाता है?", "oh": ["लिग्नाइट", "लौह अयस्क", "बॉक्साइट", "अभ्रक"], "eh": "नेवेली (कडलूर ज़िला) में भारत की सबसे बड़ी लिग्नाइट खदानें हैं, जिन्हें NLC इंडिया चलाती है।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The Supreme Court of India is established under which Article?", "o": ["Article 214", "Article 32", "Article 124", "Article 131"], "a": 2, "e": "Article 124 establishes the Supreme Court; Article 214 provides a High Court for each State.", "qh": "भारत का सर्वोच्च न्यायालय किस अनुच्छेद के तहत स्थापित है?", "oh": ["अनुच्छेद 214", "अनुच्छेद 32", "अनुच्छेद 124", "अनुच्छेद 131"], "eh": "अनुच्छेद 124 सर्वोच्च न्यायालय की स्थापना करता है; अनुच्छेद 214 हर राज्य के लिए उच्च न्यायालय देता है।", "level": "easy"}, {"s": "General Awareness", "t": "Awards", "q": "UNESCO's Kalinga Prize is given for:", "o": ["Peace", "Literature", "Environmental journalism", "Popularisation of science"], "a": 3, "e": "The Kalinga Prize, instituted in 1952 with a donation from Biju Patnaik, honours the popularisation of science.", "qh": "यूनेस्को का कलिंग पुरस्कार किसके लिए दिया जाता है?", "oh": ["शांति", "साहित्य", "पर्यावरण पत्रकारिता", "विज्ञान को लोकप्रिय बनाने"], "eh": "बीजू पटनायक के दान से 1952 में शुरू कलिंग पुरस्कार विज्ञान को लोकप्रिय बनाने के लिए दिया जाता है।", "level": "tough"}, {"s": "General Awareness", "t": "Awards", "q": "The 2026 World Food Prize was awarded to Huub Lelieveld for his work in:", "o": ["Hybrid rice breeding", "Drip irrigation", "Global food safety standards", "Biofortified wheat"], "a": 2, "e": "Dutch scientist Huub Lelieveld, called the architect of global food safety standards, received the 2026 World Food Prize (ceremony 22 October 2026).", "qh": "2026 का विश्व खाद्य पुरस्कार ह्यूब लेलीवेल्ड को किस क्षेत्र में काम के लिए मिला?", "oh": ["संकर धान प्रजनन", "ड्रिप सिंचाई", "वैश्विक खाद्य सुरक्षा मानक", "जैव-संवर्धित गेहूँ"], "eh": "डच वैज्ञानिक ह्यूब लेलीवेल्ड, जिन्हें वैश्विक खाद्य सुरक्षा मानकों का निर्माता कहा जाता है, को 2026 का विश्व खाद्य पुरस्कार मिला (समारोह 22 अक्टूबर 2026)।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "Through which pass does the Sutlej river enter India from Tibet?", "o": ["Nathu La", "Bomdila", "Zoji La", "Shipki La"], "a": 3, "e": "The Sutlej enters Himachal Pradesh through the Shipki La pass in Kinnaur district.", "qh": "सतलुज नदी तिब्बत से किस दर्रे से भारत में प्रवेश करती है?", "oh": ["नाथू ला", "बोमडिला", "ज़ोजी ला", "शिपकी ला"], "eh": "सतलुज हिमाचल प्रदेश के किन्नौर ज़िले में शिपकी ला दर्रे से भारत में आती है।", "level": "tough"}, {"s": "General Awareness", "t": "Computer", "q": "An IPv4 address is made up of how many bits?", "o": ["64", "128", "32", "16"], "a": 2, "e": "IPv4 uses 32-bit addresses (four numbers 0–255); IPv6 uses 128 bits.", "qh": "IPv4 पता कितने बिट का होता है?", "oh": ["64", "128", "32", "16"], "eh": "IPv4 में 32 बिट के पते (0–255 की चार संख्याएँ) होते हैं; IPv6 में 128 बिट।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "Pellagra is caused by the deficiency of:", "o": ["Niacin (vitamin B3)", "Riboflavin (vitamin B2)", "Vitamin K", "Vitamin A"], "a": 0, "e": "Pellagra, marked by dermatitis, diarrhoea and dementia, results from lack of niacin.", "qh": "पेलाग्रा किसकी कमी से होता है?", "oh": ["नियासिन (विटामिन B3)", "राइबोफ़्लेविन (विटामिन B2)", "विटामिन K", "विटामिन A"], "eh": "त्वचा रोग, दस्त और मनोभ्रंश वाला पेलाग्रा नियासिन की कमी से होता है।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Pandit Ravi Shankar was a world-famous player of the:", "o": ["Sarod", "Santoor", "Shehnai", "Sitar"], "a": 3, "e": "Ravi Shankar took the sitar to world audiences and won three Grammys; he received the Bharat Ratna in 1999.", "qh": "पंडित रविशंकर किस वाद्य के विश्व-प्रसिद्ध वादक थे?", "oh": ["सरोद", "संतूर", "शहनाई", "सितार"], "eh": "रविशंकर सितार को दुनिया भर में ले गए और तीन ग्रैमी जीते; उन्हें 1999 में भारत रत्न मिला।", "level": "easy"}, {"s": "General Awareness", "t": "Static GK", "q": "Constitution Day (Samvidhan Divas) is observed in India on:", "o": ["26 January", "15 August", "26 November", "2 October"], "a": 2, "e": "The Constituent Assembly adopted the Constitution on 26 November 1949; it came into force on 26 January 1950.", "qh": "भारत में संविधान दिवस कब मनाया जाता है?", "oh": ["26 जनवरी", "15 अगस्त", "26 नवंबर", "2 अक्टूबर"], "eh": "संविधान सभा ने 26 नवंबर 1949 को संविधान अपनाया; यह 26 जनवरी 1950 को लागू हुआ।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Vembanad, the longest lake in India, is in which state?", "o": ["Tamil Nadu", "Kerala", "Karnataka", "Andhra Pradesh"], "a": 1, "e": "Vembanad Lake spans Alappuzha, Kottayam and Ernakulam districts of Kerala.", "qh": "भारत की सबसे लंबी झील वेम्बनाड किस राज्य में है?", "oh": ["तमिलनाडु", "केरल", "कर्नाटक", "आंध्र प्रदेश"], "eh": "वेम्बनाड झील केरल के अलप्पुझा, कोट्टायम और एर्नाकुलम ज़िलों में फैली है।", "level": "easy"}, {"s": "General Awareness", "t": "General Science", "q": "The time in which half of the nuclei of a radioactive sample decay is called its:", "o": ["Mean free path", "Time period", "Relaxation time", "Half-life"], "a": 3, "e": "Half-life is constant for a given isotope; for example carbon-14 has a half-life of about 5,730 years.", "qh": "जितने समय में किसी रेडियोधर्मी नमूने के आधे नाभिक क्षय हो जाते हैं, उसे क्या कहते हैं?", "oh": ["माध्य मुक्त पथ", "आवर्त काल", "विश्रांति काल", "अर्ध-आयु"], "eh": "किसी समस्थानिक की अर्ध-आयु स्थिर रहती है; जैसे कार्बन-14 की अर्ध-आयु लगभग 5,730 साल है।", "level": "tough"}, {"s": "General Awareness", "t": "Science & Tech", "q": "Who is regarded as the father of the Indian space programme?", "o": ["Vikram Sarabhai", "Homi J. Bhabha", "Satish Dhawan", "A. P. J. Abdul Kalam"], "a": 0, "e": "Vikram Sarabhai founded INCOSPAR (1962), which became ISRO in 1969. Homi Bhabha led the nuclear programme.", "qh": "भारतीय अंतरिक्ष कार्यक्रम का जनक किसे माना जाता है?", "oh": ["विक्रम साराभाई", "होमी जे. भाभा", "सतीश धवन", "ए. पी. जे. अब्दुल कलाम"], "eh": "विक्रम साराभाई ने INCOSPAR (1962) बनाया, जो 1969 में ISRO बना। होमी भाभा ने परमाणु कार्यक्रम चलाया।", "level": "easy"}, {"s": "General Awareness", "t": "Railways", "q": "Hajipur is the headquarters of which railway zone?", "o": ["Eastern Railway", "North Eastern Railway", "East Coast Railway", "East Central Railway"], "a": 3, "e": "East Central Railway is headquartered at Hajipur (Bihar); Eastern – Kolkata, North Eastern – Gorakhpur, East Coast – Bhubaneswar.", "qh": "हाजीपुर किस रेलवे ज़ोन का मुख्यालय है?", "oh": ["पूर्वी रेलवे", "पूर्वोत्तर रेलवे", "पूर्व तटीय रेलवे", "पूर्व मध्य रेलवे"], "eh": "पूर्व मध्य रेलवे का मुख्यालय हाजीपुर (बिहार) में है; पूर्वी – कोलकाता, पूर्वोत्तर – गोरखपुर, पूर्व तटीय – भुवनेश्वर।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The administration of tribal areas in Assam, Meghalaya, Tripura and Mizoram is covered by which Schedule?", "o": ["Fifth Schedule", "Eighth Schedule", "Tenth Schedule", "Sixth Schedule"], "a": 3, "e": "The Sixth Schedule provides Autonomous District Councils for these four states; the Fifth Schedule covers Scheduled Areas elsewhere.", "qh": "असम, मेघालय, त्रिपुरा और मिज़ोरम के जनजातीय क्षेत्रों का प्रशासन किस अनुसूची में है?", "oh": ["पाँचवीं अनुसूची", "आठवीं अनुसूची", "दसवीं अनुसूची", "छठी अनुसूची"], "eh": "छठी अनुसूची इन चार राज्यों में स्वायत्त ज़िला परिषदें बनाती है; पाँचवीं अनुसूची बाकी अनुसूचित क्षेत्रों के लिए है।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "India's first Petroglyph Conservation Park, inaugurated in October 2026, is at:", "o": ["Sindhu Ghat, Leh", "Bhimbetka, Madhya Pradesh", "Hampi, Karnataka", "Edakkal, Kerala"], "a": 0, "e": "PM Modi inaugurated the Petroglyph Conservation Park at Sindhu Ghat, Leh, on 15 October 2026 among five Ladakh projects worth ₹3,350 crore.", "qh": "अक्टूबर 2026 में उद्घाटित भारत का पहला पेट्रोग्लिफ़ (शैलचित्र) संरक्षण पार्क कहाँ है?", "oh": ["सिंधु घाट, लेह", "भीमबेटका, मध्य प्रदेश", "हम्पी, कर्नाटक", "एडक्कल, केरल"], "eh": "प्रधानमंत्री मोदी ने 15 अक्टूबर 2026 को ₹3,350 करोड़ की पाँच लद्दाख परियोजनाओं में लेह के सिंधु घाट पर पेट्रोग्लिफ़ संरक्षण पार्क का उद्घाटन किया।", "level": "tough"}, {"s": "General Awareness", "t": "Economy", "q": "In the Global Innovation Index 2026 released by WIPO, India was ranked:", "o": ["39th", "40th", "48th", "38th"], "a": 3, "e": "WIPO's Global Innovation Index 2026 ranked India 38th among the economies covered.", "qh": "WIPO द्वारा जारी वैश्विक नवाचार सूचकांक 2026 में भारत का स्थान क्या रहा?", "oh": ["39वाँ", "40वाँ", "48वाँ", "38वाँ"], "eh": "वैश्विक नवाचार सूचकांक 2026 में भारत 38वें स्थान पर रहा।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "The Khilafat Movement (1919–24) in India was led by:", "o": ["The Ali brothers – Muhammad Ali and Shaukat Ali", "Muhammad Ali Jinnah and Liaquat Ali Khan", "Sir Syed Ahmad Khan and Mohsin-ul-Mulk", "Muhammad Iqbal and Rahmat Ali"], "a": 0, "e": "The Ali brothers led the Khilafat Movement, which Gandhi joined with Non-Cooperation.", "qh": "भारत में ख़िलाफ़त आंदोलन (1919–24) का नेतृत्व किसने किया?", "oh": ["अली बंधुओं – मुहम्मद अली और शौकत अली", "मुहम्मद अली जिन्ना और लियाक़त अली ख़ान", "सर सैयद अहमद ख़ान और मोहसिन-उल-मुल्क", "मुहम्मद इक़बाल और रहमत अली"], "eh": "अली बंधुओं ने ख़िलाफ़त आंदोलन चलाया, जिसे गांधीजी ने असहयोग आंदोलन से जोड़ा।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Doddabetta is the highest peak of which hills?", "o": ["Cardamom Hills", "Nilgiri Hills", "Anaimalai Hills", "Palani Hills"], "a": 1, "e": "Doddabetta (2,637 m) near Ooty is the highest point of the Nilgiris.", "qh": "डोडाबेट्टा किन पहाड़ियों की सबसे ऊँची चोटी है?", "oh": ["इलायची पहाड़ियाँ", "नीलगिरि पहाड़ियाँ", "अन्नामलाई पहाड़ियाँ", "पलनी पहाड़ियाँ"], "eh": "ऊटी के पास डोडाबेट्टा (2,637 m) नीलगिरि का सबसे ऊँचा स्थान है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Megasthenes, the Greek author of 'Indica', came to the court of:", "o": ["Ashoka", "Harshavardhana", "Kanishka", "Chandragupta Maurya"], "a": 3, "e": "Seleucus Nicator sent Megasthenes as ambassador to Chandragupta Maurya's court at Pataliputra.", "qh": "'इंडिका' के यूनानी लेखक मेगस्थनीज़ किसके दरबार में आए थे?", "oh": ["अशोक", "हर्षवर्धन", "कनिष्क", "चंद्रगुप्त मौर्य"], "eh": "सेल्यूकस निकेटर ने मेगस्थनीज़ को पाटलिपुत्र में चंद्रगुप्त मौर्य के दरबार में राजदूत बनाकर भेजा।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who was elected President of the 81st session of the UN General Assembly (2026–27)?", "o": ["Annalena Baerbock of Germany", "Philemon Yang of Cameroon", "Khalilur Rahman of Bangladesh", "Dennis Francis of Trinidad and Tobago"], "a": 2, "e": "Bangladesh's Khalilur Rahman was elected President of UNGA-81. Baerbock (80th), Yang (79th) and Francis (78th) were earlier Presidents.", "qh": "संयुक्त राष्ट्र महासभा के 81वें सत्र (2026–27) का अध्यक्ष किसे चुना गया?", "oh": ["जर्मनी की अनालेना बेयरबॉक", "कैमरून के फ़िलेमॉन यांग", "बांग्लादेश के ख़लीलुर रहमान", "त्रिनिदाद और टोबैगो के डेनिस फ़्रांसिस"], "eh": "बांग्लादेश के ख़लीलुर रहमान UNGA-81 के अध्यक्ष चुने गए। बेयरबॉक (80वाँ), यांग (79वाँ) और फ़्रांसिस (78वाँ) पहले अध्यक्ष थे।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Under which Article can new All India Services be created if the Rajya Sabha passes a resolution?", "o": ["Article 315", "Article 320", "Article 312", "Article 309"], "a": 2, "e": "Article 312 lets Parliament create All India Services after a Rajya Sabha resolution supported by two-thirds of members present and voting.", "qh": "किस अनुच्छेद के तहत राज्यसभा के प्रस्ताव पर नई अखिल भारतीय सेवाएँ बनाई जा सकती हैं?", "oh": ["अनुच्छेद 315", "अनुच्छेद 320", "अनुच्छेद 312", "अनुच्छेद 309"], "eh": "अनुच्छेद 312 के तहत राज्यसभा में उपस्थित और मतदान करने वाले दो-तिहाई सदस्यों के प्रस्ताव के बाद संसद अखिल भारतीय सेवाएँ बना सकती है।", "level": "tough"}, {"s": "General Awareness", "t": "Sports", "q": "Where was the opening ceremony of the Milano Cortina 2026 Winter Paralympics held on 6 March 2026?", "o": ["San Siro Stadium, Milan", "Arena di Verona", "Colosseum, Rome", "Olympic Stadium, Cortina"], "a": 1, "e": "The Winter Paralympics opened on 6 March 2026 in the Roman amphitheatre Arena di Verona and ran until 15 March 2026 in northern Italy. India did not send any athlete. (The Winter Olympics were held 6–22 February 2026.)", "qh": "6 मार्च 2026 को मिलानो कोर्टिना 2026 शीतकालीन पैरालंपिक का उद्घाटन समारोह कहाँ हुआ?", "oh": ["सान सीरो स्टेडियम, मिलान", "एरीना दी वेरोना", "कोलोसियम, रोम", "ओलंपिक स्टेडियम, कोर्टिना"], "eh": "शीतकालीन पैरालंपिक 6 मार्च 2026 को रोमन एम्फ़ीथिएटर एरीना दी वेरोना में शुरू हुए और उत्तरी इटली में 15 मार्च 2026 तक चले। भारत ने कोई खिलाड़ी नहीं भेजा। (शीतकालीन ओलंपिक 6–22 फ़रवरी 2026 को हुए।)", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "Small text files that websites store in a user's browser to remember settings or logins are called:", "o": ["Cache servers", "Cookies", "Plug-ins", "Macros"], "a": 1, "e": "Cookies are saved by the browser for a website and sent back on later visits.", "qh": "वेबसाइटें सेटिंग या लॉगिन याद रखने के लिए उपयोगकर्ता के ब्राउज़र में जो छोटी टेक्स्ट फ़ाइलें रखती हैं, उन्हें क्या कहते हैं?", "oh": ["कैश सर्वर", "कुकीज़", "प्लग-इन", "मैक्रो"], "eh": "कुकीज़ ब्राउज़र किसी वेबसाइट के लिए सहेजता है और अगली बार उसे वापस भेजता है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The India–UK Comprehensive Economic and Trade Agreement (CETA) came into force on:", "o": ["15 July 2026", "24 July 2025", "1 April 2026", "26 January 2026"], "a": 0, "e": "The CETA, signed on 24 July 2025, entered into force on 15 July 2026.", "qh": "भारत–ब्रिटेन व्यापक आर्थिक और व्यापार समझौता (CETA) कब लागू हुआ?", "oh": ["15 जुलाई 2026", "24 जुलाई 2025", "1 अप्रैल 2026", "26 जनवरी 2026"], "eh": "24 जुलाई 2025 को हस्ताक्षरित CETA 15 जुलाई 2026 को लागू हुआ।", "level": "medium"}, {"s": "General Awareness", "t": "Sports", "q": "The Beighton Cup, one of the oldest tournaments of its kind in the world, is associated with:", "o": ["Football", "Cricket", "Hockey", "Badminton"], "a": 2, "e": "The Beighton Cup, started in Kolkata in 1895, is a field hockey tournament.", "qh": "दुनिया के अपनी तरह के सबसे पुराने टूर्नामेंटों में से एक बेटन कप किस खेल से जुड़ा है?", "oh": ["फ़ुटबॉल", "क्रिकेट", "हॉकी", "बैडमिंटन"], "eh": "1895 में कोलकाता में शुरू हुआ बेटन कप एक हॉकी टूर्नामेंट है।", "level": "tough"}, {"s": "General Awareness", "t": "Economy", "q": "The share of deposits that banks must keep in liquid assets such as cash, gold and government securities is called:", "o": ["Cash Reserve Ratio (CRR)", "Marginal Standing Facility (MSF)", "Statutory Liquidity Ratio (SLR)", "Repo rate"], "a": 2, "e": "SLR is kept by banks themselves in approved liquid assets; CRR is kept with the RBI.", "qh": "बैंकों को अपनी जमा का जो हिस्सा नकद, सोना और सरकारी प्रतिभूतियों जैसी तरल संपत्तियों में रखना होता है, उसे क्या कहते हैं?", "oh": ["नकद आरक्षित अनुपात (CRR)", "सीमांत स्थायी सुविधा (MSF)", "सांविधिक तरलता अनुपात (SLR)", "रेपो रेट"], "eh": "SLR बैंक खुद मान्य तरल संपत्तियों में रखते हैं; CRR RBI के पास रखा जाता है।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The Inter-State Council was set up in 1990 on the recommendation of which commission?", "o": ["Punchhi Commission", "Sarkaria Commission", "Kothari Commission", "Mandal Commission"], "a": 1, "e": "The Sarkaria Commission on Centre–State relations recommended a permanent Inter-State Council under Article 263.", "qh": "अंतर-राज्य परिषद 1990 में किस आयोग की सिफ़ारिश पर बनाई गई?", "oh": ["पुंछी आयोग", "सरकारिया आयोग", "कोठारी आयोग", "मंडल आयोग"], "eh": "केंद्र–राज्य संबंधों पर सरकारिया आयोग ने अनुच्छेद 263 के तहत स्थायी अंतर-राज्य परिषद की सिफ़ारिश की थी।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "Gandhiji's Champaran Satyagraha (1917) was organised for:", "o": ["Indigo cultivators", "Mill workers", "Salt makers", "Tea garden labourers"], "a": 0, "e": "In Champaran (Bihar) peasants were forced to grow indigo under the tinkathia system; Gandhi's campaign ended it.", "qh": "गांधीजी का चंपारण सत्याग्रह (1917) किनके लिए था?", "oh": ["नील की खेती करने वाले किसान", "मिल मज़दूर", "नमक बनाने वाले", "चाय बागान मज़दूर"], "eh": "चंपारण (बिहार) में किसानों को तिनकठिया प्रथा में नील उगाने को मजबूर किया जाता था; गांधीजी के आंदोलन ने इसे खत्म कराया।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Moroccan traveller Ibn Battuta visited India during the reign of:", "o": ["Muhammad bin Tughlaq", "Alauddin Khalji", "Akbar", "Iltutmish"], "a": 0, "e": "Ibn Battuta reached India in 1333 and served as qazi of Delhi under Muhammad bin Tughlaq; he wrote the Rihla.", "qh": "मोरक्को के यात्री इब्न बतूता किसके शासनकाल में भारत आए?", "oh": ["मुहम्मद बिन तुग़लक़", "अलाउद्दीन ख़िलजी", "अकबर", "इल्तुतमिश"], "eh": "इब्न बतूता 1333 में भारत आए और मुहम्मद बिन तुग़लक़ के समय दिल्ली के क़ाज़ी रहे; उन्होंने 'रिहला' लिखी।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "Raindrops are nearly spherical mainly because of:", "o": ["Viscosity", "Buoyancy", "Air pressure", "Surface tension"], "a": 3, "e": "Surface tension pulls a liquid into the shape with the least surface area, a sphere.", "qh": "बारिश की बूँदें लगभग गोल मुख्य रूप से किस कारण होती हैं?", "oh": ["श्यानता", "उत्प्लावन", "वायु दाब", "पृष्ठ तनाव"], "eh": "पृष्ठ तनाव द्रव को सबसे कम सतह वाले आकार, यानी गोले, में खींचता है।", "level": "medium"}, {"s": "General Awareness", "t": "Static GK", "q": "The fictional town of 'Malgudi' appears in the works of:", "o": ["Mulk Raj Anand", "Ruskin Bond", "Vikram Seth", "R. K. Narayan"], "a": 3, "e": "R. K. Narayan set Swami and Friends, The Guide and other works in Malgudi.", "qh": "काल्पनिक कस्बा 'मालगुडी' किसकी रचनाओं में आता है?", "oh": ["मुल्क राज आनंद", "रस्किन बॉन्ड", "विक्रम सेठ", "आर. के. नारायण"], "eh": "आर. के. नारायण ने 'स्वामी एंड फ़्रेंड्स', 'द गाइड' आदि की कहानी मालगुडी में रखी।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Noida International Airport, which began commercial flights on 15 June 2026, is located at:", "o": ["Jewar, Gautam Buddh Nagar (Uttar Pradesh)", "Hindon, Ghaziabad (Uttar Pradesh)", "Palwal (Haryana)", "Greater Noida West (Uttar Pradesh)"], "a": 0, "e": "Noida International Airport at Jewar began commercial operations on 15 June 2026 with an IndiGo flight from Lucknow.", "qh": "15 जून 2026 को व्यावसायिक उड़ानें शुरू करने वाला नोएडा अंतरराष्ट्रीय हवाई अड्डा कहाँ है?", "oh": ["जेवर, गौतम बुद्ध नगर (उत्तर प्रदेश)", "हिंडन, ग़ाज़ियाबाद (उत्तर प्रदेश)", "पलवल (हरियाणा)", "ग्रेटर नोएडा वेस्ट (उत्तर प्रदेश)"], "eh": "जेवर स्थित नोएडा अंतरराष्ट्रीय हवाई अड्डे ने 15 जून 2026 को लखनऊ से इंडिगो की उड़ान के साथ व्यावसायिक संचालन शुरू किया।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Which Chola ruler took the title 'Gangaikonda' and built the city of Gangaikonda Cholapuram?", "o": ["Rajaraja I", "Karikala", "Rajendra I", "Kulottunga I"], "a": 2, "e": "Rajendra I took the title after his northern campaign to the Ganga and built Gangaikonda Cholapuram as his capital.", "qh": "किस चोल शासक ने 'गंगैकोंड' उपाधि ली और गंगैकोंड चोलपुरम नगर बसाया?", "oh": ["राजराज प्रथम", "करिकाल", "राजेंद्र प्रथम", "कुलोत्तुंग प्रथम"], "eh": "राजेंद्र प्रथम ने गंगा तक के अभियान के बाद यह उपाधि ली और गंगैकोंड चोलपुरम को राजधानी बनाया।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "The Simon Commission (1928) was boycotted in India mainly because:", "o": ["It proposed the partition of Bengal", "It had no Indian member", "It abolished provincial legislatures", "It was headed by an Indian"], "a": 1, "e": "All seven members of the Simon Commission were British, so Indians greeted it with 'Simon Go Back'.", "qh": "भारत में साइमन कमीशन (1928) का बहिष्कार मुख्य रूप से क्यों किया गया?", "oh": ["इसने बंगाल विभाजन का प्रस्ताव रखा", "इसमें एक भी भारतीय सदस्य नहीं था", "इसने प्रांतीय विधानमंडल खत्म कर दिए", "इसके अध्यक्ष एक भारतीय थे"], "eh": "साइमन कमीशन के सभी सात सदस्य अंग्रेज़ थे, इसलिए भारतीयों ने 'साइमन गो बैक' के नारे लगाए।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which of these is a kharif crop?", "o": ["Rice", "Wheat", "Mustard", "Gram"], "a": 0, "e": "Kharif crops are sown with the monsoon (June–July) and harvested in autumn; wheat, mustard and gram are rabi crops.", "qh": "इनमें से कौन-सी ख़रीफ़ फ़सल है?", "oh": ["धान", "गेहूँ", "सरसों", "चना"], "eh": "ख़रीफ़ फ़सलें मानसून (जून–जुलाई) के साथ बोई जाती हैं और पतझड़ में कटती हैं; गेहूँ, सरसों और चना रबी फ़सलें हैं।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Kudankulam Nuclear Power Plant is in which state?", "o": ["Kerala", "Tamil Nadu", "Karnataka", "Andhra Pradesh"], "a": 1, "e": "Kudankulam (Tirunelveli district, Tamil Nadu) was built with Russian collaboration.", "qh": "कुडनकुलम परमाणु बिजलीघर किस राज्य में है?", "oh": ["केरल", "तमिलनाडु", "कर्नाटक", "आंध्र प्रदेश"], "eh": "कुडनकुलम (तिरुनेलवेली ज़िला, तमिलनाडु) रूस के सहयोग से बना है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Who discovered electromagnetic induction in 1831?", "o": ["James Clerk Maxwell", "André-Marie Ampère", "Michael Faraday", "Georg Ohm"], "a": 2, "e": "Faraday showed that a changing magnetic field induces current in a coil; this is the basis of generators and transformers.", "qh": "1831 में विद्युत-चुंबकीय प्रेरण की खोज किसने की?", "oh": ["जेम्स क्लर्क मैक्सवेल", "आंद्रे-मारी एम्पियर", "माइकल फ़ैराडे", "जॉर्ज ओम"], "eh": "फ़ैराडे ने दिखाया कि बदलता चुंबकीय क्षेत्र कुंडली में धारा पैदा करता है; जनरेटर और ट्रांसफ़ॉर्मर इसी पर चलते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The Contingency Fund of India is placed at the disposal of:", "o": ["The Prime Minister", "The President", "The Finance Minister", "The Comptroller and Auditor General"], "a": 1, "e": "Under Article 267, the Contingency Fund is at the disposal of the President to meet unforeseen expenditure.", "qh": "भारत की आकस्मिकता निधि किसके अधिकार में रखी जाती है?", "oh": ["प्रधानमंत्री", "राष्ट्रपति", "वित्त मंत्री", "नियंत्रक एवं महालेखा परीक्षक"], "eh": "अनुच्छेद 267 के तहत अप्रत्याशित खर्च के लिए आकस्मिकता निधि राष्ट्रपति के अधिकार में रहती है।", "level": "medium"}, {"s": "Mathematics", "t": "Time and Work", "q": "Manoj is 2 times as efficient as Naveen. Working together, they finish a job in 16 days. In how many days can Manoj alone finish it?", "o": ["48 days", "24 days", "40 days", "64 days"], "a": 1, "e": "Efficiencies 2 : 1, total 3 units/day; work = 3 × 16 = 48 units. Manoj alone: 48/2 = 24 days.", "qh": "मनोज, नवीन से 2 गुना कुशल है। दोनों मिलकर एक काम 16 दिन में पूरा करते हैं। अकेला मनोज इसे कितने दिन में पूरा कर सकता है?", "oh": ["48 दिन", "24 दिन", "40 दिन", "64 दिन"], "eh": "कुशलता 2 : 1, कुल 3 इकाई/दिन; काम = 3 × 16 = 48 इकाई। अकेला मनोज: 48/2 = 24 दिन।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "A two-digit number has digits adding up to 7. Interchanging its digits increases the number by 45. Find the number.", "o": ["34", "52", "25", "16"], "a": 3, "e": "9(u − t) = 45 → u − t = 5; u + t = 7 → u = 6, t = 1; number = 16.", "qh": "दो अंकों की एक संख्या के अंकों का योग 7 है। अंकों की जगह बदलने से संख्या 45 बढ़ जाती है। संख्या बताइए।", "oh": ["34", "52", "25", "16"], "eh": "9(u − t) = 45 → u − t = 5; u + t = 7 → u = 6, t = 1; संख्या = 16।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "Anjali's salary is 60% more than Naveen's salary. By what percentage is Naveen's salary less than Anjali's?", "o": ["42.5%", "30%", "37.5%", "40%"], "a": 2, "e": "Take Naveen = 100, Anjali = 160. Less by 60/160 × 100 = 37.5%.", "qh": "अंजलि की तनख्वाह नवीन की तनख्वाह से 60% ज़्यादा है। नवीन की तनख्वाह अंजलि की तनख्वाह से कितने प्रतिशत कम है?", "oh": ["42.5%", "30%", "37.5%", "40%"], "eh": "नवीन = 100 मानें, अंजलि = 160। कम = 60/160 × 100 = 37.5%।", "level": "tough"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "The speed of a boat in still water is 10 km/h and the speed of the stream is 2 km/h. How long will it take to go 36 km downstream?", "o": ["4.5 hours", "6 hours", "3.6 hours", "3 hours"], "a": 3, "e": "Downstream speed = 10 + 2 = 12 km/h; time = 36/12 = 3 hours.", "qh": "शांत पानी में नाव की रफ़्तार 10 km/h और धारा की रफ़्तार 2 km/h है। धारा के साथ 36 km जाने में कितना समय लगेगा?", "oh": ["4.5 घंटे", "6 घंटे", "3.6 घंटे", "3 घंटे"], "eh": "धारा के साथ रफ़्तार = 10 + 2 = 12 km/h; समय = 36/12 = 3 घंटे।", "level": "easy"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: √729 + √64 × ∛8 = ?", "o": ["37", "43", "45", "70"], "a": 1, "e": "√729 = 27, √64 = 8, ∛8 = 2; 27 + 8 × 2 = 43.", "qh": "सरल कीजिए: √729 + √64 × ∛8 = ?", "oh": ["37", "43", "45", "70"], "eh": "√729 = 27, √64 = 8, ∛8 = 2; 27 + 8 × 2 = 43।", "level": "easy"}, {"s": "Mathematics", "t": "Interest", "q": "A sum lent at simple interest becomes double the principal after 25 years. Find the annual rate of interest.", "o": ["8%", "2%", "6%", "4%"], "a": 3, "e": "Interest = 1 × P = P × R × 25/100 → R = 100/25 = 4%.", "qh": "साधारण ब्याज पर दी गई एक राशि 25 साल बाद मूलधन की दोगुनी हो जाती है। वार्षिक ब्याज दर बताइए।", "oh": ["8%", "2%", "6%", "4%"], "eh": "ब्याज = 1 × P = P × R × 25/100 → R = 100/25 = 4%।", "level": "tough"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 13 + 20 × 7 − 8 ÷ 2 + 12²", "o": ["295", "293", "290", "303"], "a": 1, "e": "Follow BODMAS (brackets, then ÷ and × from left to right, then + and −): value = 293.", "qh": "सरल कीजिए: 13 + 20 × 7 − 8 ÷ 2 + 12²", "oh": ["295", "293", "290", "303"], "eh": "BODMAS के नियम से (पहले कोष्ठक, फिर बाएँ से दाएँ ÷ और ×, फिर + और −): मान = 293।", "level": "medium"}, {"s": "Mathematics", "t": "Ages", "q": "The sum of the present ages of a father and son is 52 years. 2 years ago, the father's age was 3 times the son's age. What is the present age of the son?", "o": ["12 years", "16 years", "14 years", "38 years"], "a": 2, "e": "Let son = x. (52 − x − 2) = 3(x − 2) → 52 − 2 + 6 = 4x → x = 14 years.", "qh": "एक पिता और बेटे की वर्तमान आयु का योग 52 साल है। 2 साल पहले पिता की आयु बेटे की आयु की 3 गुनी थी। बेटे की वर्तमान आयु क्या है?", "oh": ["12 साल", "16 साल", "14 साल", "38 साल"], "eh": "माना बेटे की आयु = x। (52 − x − 2) = 3(x − 2) → 52 − 2 + 6 = 4x → x = 14 साल।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "How many numbers from 150 to 500 are divisible by both 4 and 10?", "o": ["18", "17", "20", "36"], "a": 0, "e": "Divisible by both = divisible by LCM 20: ⌊500/20⌋ − ⌊149/20⌋ = 18.", "qh": "150 से 500 तक कितनी संख्याएँ 4 और 10 दोनों से विभाज्य हैं?", "oh": ["18", "17", "20", "36"], "eh": "दोनों से विभाज्य = LCM से विभाज्य 20: ⌊500/20⌋ − ⌊149/20⌋ = 18।", "level": "medium"}, {"s": "Mathematics", "t": "Time and Work", "q": "24 workers can build a wall in 18 days. How many days will 9 workers take to build the same wall?", "o": ["47 days", "48 days", "6.75 days", "50 days"], "a": 1, "e": "Work = 24 × 18 = 432 worker-days. Days = 432/9 = 48.", "qh": "24 मज़दूर एक दीवार 18 दिन में बना सकते हैं। 9 मज़दूर वही दीवार कितने दिन में बनाएँगे?", "oh": ["47 दिन", "48 दिन", "6.75 दिन", "50 दिन"], "eh": "काम = 24 × 18 = 432 मज़दूर-दिन। दिन = 432/9 = 48।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "The edge of a cube is 5 cm. What is its total surface area?", "o": ["60 cm²", "150 cm²", "125 cm²", "156 cm²"], "a": 1, "e": "6a² = 6 × 5² = 150 cm².", "qh": "एक घन की भुजा 5 cm है। उसका कुल पृष्ठीय क्षेत्रफल कितना है?", "oh": ["60 cm²", "150 cm²", "125 cm²", "156 cm²"], "eh": "6a² = 6 × 5² = 150 cm²।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "What is the unit digit of 7^33?", "o": ["7", "9", "2", "8"], "a": 0, "e": "Unit digits of powers of 7 repeat as 7, 9, 3, 1 (cycle 4). 33 mod 4 = 1 → unit digit 7.", "qh": "7^33 का इकाई अंक क्या है?", "oh": ["7", "9", "2", "8"], "eh": "7 की घातों के इकाई अंक 7, 9, 3, 1 दोहराते हैं (चक्र 4)। 33 को 4 से भाग देने पर 1 → इकाई अंक 7।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "The cost price of an article is ₹2,400. It is marked 30% above the cost price and sold at a discount of 20%. What is the selling price?", "o": ["₹2,496", "₹3,120", "₹2,640", "₹2,546"], "a": 0, "e": "MP = ₹2,400 × 1.3 = ₹3,120; SP = MP × 0.8 = ₹2,496.", "qh": "एक वस्तु का क्रय मूल्य ₹2,400 है। उस पर क्रय मूल्य से 30% ज़्यादा दाम लिखा जाता है और 20% छूट पर बेचा जाता है। विक्रय मूल्य क्या है?", "oh": ["₹2,496", "₹3,120", "₹2,640", "₹2,546"], "eh": "अंकित मूल्य = ₹2,400 × 1.3 = ₹3,120; विक्रय मूल्य = अंकित मूल्य × 0.8 = ₹2,496।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "By selling 45 notebooks, a trader gains the selling price of 20 notebooks. What is his gain percentage?", "o": ["160%", "30 10/13%", "44 4/9%", "80%"], "a": 3, "e": "Gain = SP of 20, so CP of 45 = SP of 25. Gain % = 20/25 × 100 = 80%.", "qh": "45 कॉपियाँ बेचकर एक व्यापारी को 20 कॉपियाँ के विक्रय मूल्य के बराबर लाभ होता है। उसका लाभ प्रतिशत क्या है?", "oh": ["160%", "30 10/13%", "44 4/9%", "80%"], "eh": "लाभ = 20 का विक्रय मूल्य, इसलिए 45 का क्रय मूल्य = 25 का विक्रय मूल्य। लाभ % = 20/25 × 100 = 80%।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The incomes of Rohit and Arjun are in the ratio 4 : 3 and their expenditures are in the ratio 5 : 3. If each of them saves ₹1,200, what is Rohit's income?", "o": ["₹2,000", "₹3,200", "₹2,400", "₹2,200"], "a": 1, "e": "4x − 5y = 3x − 3y = 1200 → 1x = 2y. Solving: x = 800, y = 400, so income = 4 × 800 = ₹3,200.", "qh": "रोहित और अर्जुन की आय का अनुपात 4 : 3 और खर्च का अनुपात 5 : 3 है। अगर दोनों ₹1,200 बचाते हैं, तो रोहित की आय कितनी है?", "oh": ["₹2,000", "₹3,200", "₹2,400", "₹2,200"], "eh": "4x − 5y = 3x − 3y = 1200 → 1x = 2y। हल करने पर x = 800, y = 400, आय = 4 × 800 = ₹3,200।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "The population of a town is 25,000. It increases by 10% in the first year and by 5% in the second year. What is the population after 2 years?", "o": ["28,875", "27,500", "28,750", "28,675"], "a": 0, "e": "25,000 × 1.1 × 1.05 = 28,875.", "qh": "एक कस्बे की आबादी 25,000 है। यह पहले साल 10% बढ़ती है और दूसरे साल 5% बढ़ती है। 2 साल बाद आबादी कितनी होगी?", "oh": ["28,875", "27,500", "28,750", "28,675"], "eh": "25,000 × 1.1 × 1.05 = 28,875।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "What is the unit digit of 7^64 + 9^59?", "o": ["5", "0", "4", "6"], "a": 1, "e": "Unit digit of 7^64 = 1, of 9^59 = 9. 1 + 9 → unit digit 0.", "qh": "7^64 + 9^59 का इकाई अंक क्या है?", "oh": ["5", "0", "4", "6"], "eh": "7^64 का इकाई अंक = 1, 9^59 का = 9। 1 + 9 → इकाई अंक 0।", "level": "tough"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "What is the third proportional to 8 and 24?", "o": ["108", "74", "69", "72"], "a": 3, "e": "8 : 24 = 24 : x → x = 24²/8 = 576/8 = 72.", "qh": "8 और 24 का तीसरा समानुपाती क्या है?", "oh": ["108", "74", "69", "72"], "eh": "8 : 24 = 24 : x → x = 24²/8 = 576/8 = 72।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 9 consecutive numbers is 31. What is the largest of them?", "o": ["35", "34", "40", "36"], "a": 0, "e": "The average is the middle number 31; there are 4 numbers on each side with gap 1 → largest = 35.", "qh": "9 लगातार संख्याओं का औसत 31 है। उनमें सबसे बड़ी संख्या कौन-सी है?", "oh": ["35", "34", "40", "36"], "eh": "औसत ही बीच वाली संख्या 31 है; दोनों ओर 4 संख्याएँ, अंतर 1 → उत्तर = 35।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A shopkeeper gives a discount of 10% on the marked price of a school bag and still makes a profit of 20%. If its cost price is ₹720, what is the marked price?", "o": ["₹960", "₹1,020", "₹936", "₹920"], "a": 0, "e": "SP = ₹720 × 120/100 = ₹864; MP = SP × 100/90 = ₹960.", "qh": "एक दुकानदार एक स्कूल बैग के अंकित मूल्य पर 10% छूट देता है और फिर भी 20% लाभ कमाता है। अगर इसका क्रय मूल्य ₹720 है, तो अंकित मूल्य क्या है?", "oh": ["₹960", "₹1,020", "₹936", "₹920"], "eh": "विक्रय मूल्य = ₹720 × 120/100 = ₹864; अंकित मूल्य = विक्रय मूल्य × 100/90 = ₹960।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 9 consecutive even numbers is 54. What is the largest of them?", "o": ["60", "46", "62", "64"], "a": 2, "e": "The average is the middle number 54; there are 4 numbers on each side with gap 2 → largest = 62.", "qh": "9 लगातार सम संख्याओं का औसत 54 है। उनमें सबसे बड़ी संख्या कौन-सी है?", "oh": ["60", "46", "62", "64"], "eh": "औसत ही बीच वाली संख्या 54 है; दोनों ओर 4 संख्याएँ, अंतर 2 → उत्तर = 62।", "level": "tough"}, {"s": "Mathematics", "t": "Mensuration", "q": "The edge of a cube is 8 cm. What is its total surface area?", "o": ["256 cm²", "384 cm²", "390 cm²", "96 cm²"], "a": 1, "e": "6a² = 6 × 8² = 384 cm².", "qh": "एक घन की भुजा 8 cm है। उसका कुल पृष्ठीय क्षेत्रफल कितना है?", "oh": ["256 cm²", "384 cm²", "390 cm²", "96 cm²"], "eh": "6a² = 6 × 8² = 384 cm²।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A vendor buys 15 bananas for ₹100 and sells 12 bananas for ₹50. What is his loss percentage?", "o": ["20%", "50%", "42.5%", "37.5%"], "a": 3, "e": "CP of 1 = 20/3, SP of 1 = 25/6. Loss % = |25/6 − 20/3|/20/3 × 100 = 37.5%.", "qh": "एक विक्रेता ₹100 में 15 केले खरीदता है और ₹50 में 12 केले बेचता है। उसका हानि प्रतिशत क्या है?", "oh": ["20%", "50%", "42.5%", "37.5%"], "eh": "1 केले का क्रय मूल्य = 20/3, विक्रय मूल्य = 25/6। प्रतिशत = |25/6 − 20/3|/20/3 × 100 = 37.5%।", "level": "medium"}, {"s": "Mathematics", "t": "Geometry", "q": "The angles of a triangle are in the ratio 2 : 3 : 5. What is the difference between the largest and smallest angles?", "o": ["54°", "90°", "36°", "72°"], "a": 0, "e": "Each part = 180°/10 = 18°; angles 36°, 54°, 90° → 54°.", "qh": "एक त्रिभुज के कोण 2 : 3 : 5 के अनुपात में हैं। सबसे बड़े और सबसे छोटे कोण का अंतर क्या है?", "oh": ["54°", "90°", "36°", "72°"], "eh": "एक भाग = 180°/10 = 18°; कोण 36°, 54°, 90° → 54°।", "level": "tough"}, {"s": "Mathematics", "t": "Interest", "q": "What is the compound interest on ₹15,000 at 8% per annum for 2 years, compounded annually?", "o": ["₹2,446", "₹2,400", "₹2,496", "₹3,696"], "a": 2, "e": "Amount = 15000 × (1.08)² = ₹17,496. CI = ₹17,496 − ₹15,000 = ₹2,496.", "qh": "₹15,000 पर 8% वार्षिक दर से 2 साल का चक्रवृद्धि ब्याज (सालाना जुड़ने वाला) कितना होगा?", "oh": ["₹2,446", "₹2,400", "₹2,496", "₹3,696"], "eh": "मिश्रधन = 15000 × (1.08)² = ₹17,496। चक्रवृद्धि ब्याज = ₹17,496 − ₹15,000 = ₹2,496।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "Students of a school stand in rows of 6, 9 and 15; each time 2 students are left without a row. Find the least possible number of students.", "o": ["92", "182", "90", "93"], "a": 0, "e": "LCM(6, 9, 15) = 90; number = 90 + 2 = 92.", "qh": "एक स्कूल के छात्र 6, 9 और 15 की पंक्तियों में खड़े होते हैं; हर बार 2 छात्र किसी पंक्ति में नहीं आ पाते। छात्रों की कम से कम संभव संख्या बताइए।", "oh": ["92", "182", "90", "93"], "eh": "LCM(6, 9, 15) = 90; संख्या = 90 + 2 = 92।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "If a = 9, b = 2 and c = 3, what is the value of a² + b² + c² − ab − bc − ca?", "o": ["41", "86", "43", "94"], "a": 2, "e": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[49 + 1 + 36] = 43.", "qh": "अगर a = 9, b = 2 और c = 3 है, तो a² + b² + c² − ab − bc − ca का मान क्या है?", "oh": ["41", "86", "43", "94"], "eh": "= ½[(a − b)² + (b − c)² + (c − a)²] = ½[49 + 1 + 36] = 43।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "A 60-litre mixture contains milk and water in the ratio 4 : 1. How many litres of water must be added to make the ratio 4 : 3?", "o": ["180/7 litres", "48 litres", "29 litres", "24 litres"], "a": 3, "e": "Milk = 48 L, water = 12 L. Need 48 : (12 + x) = 4 : 3 → x = 48×3/4 − 12 = 24 L.", "qh": "60 लीटर के एक मिश्रण में दूध और पानी का अनुपात 4 : 1 है। अनुपात 4 : 3 करने के लिए इसमें कितने लीटर पानी मिलाना होगा?", "oh": ["180/7 litres", "48 litres", "29 litres", "24 litres"], "eh": "दूध = 48 L, पानी = 12 L। 48 : (12 + x) = 4 : 3 → x = 48×3/4 − 12 = 24 L।", "level": "medium"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If tan θ = 20/21, what is sin θ? (θ is acute)", "o": ["29/20", "21/20", "21/29", "20/29"], "a": 3, "e": "Opposite = 20, adjacent = 21, hypotenuse = √(20² + 21²) = 29. sin θ = 20/29.", "qh": "अगर tan θ = 20/21 है, तो sin θ क्या है? (θ न्यून कोण है)", "oh": ["29/20", "21/20", "21/29", "20/29"], "eh": "सामने की भुजा = 20, आसन्न भुजा = 21, कर्ण = √(20² + 21²) = 29. sin θ = 20/29।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A car covers 135 km in 3 hours. What is its speed in metres per second?", "o": ["17.5 m/s", "162 m/s", "12.5 m/s", "25 m/s"], "a": 2, "e": "Speed = 135/3 = 45 km/h = 45 × 5/18 = 12.5 m/s.", "qh": "एक कार 135 km की दूरी 3 घंटे में तय करती है। उसकी रफ़्तार मीटर प्रति सेकंड में कितनी है?", "oh": ["17.5 m/s", "162 m/s", "12.5 m/s", "25 m/s"], "eh": "रफ़्तार = 135/3 = 45 km/h = 45 × 5/18 = 12.5 m/s।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo keys are birds.\nSome birds are chairs.\nConclusions:\nI. No chairs are keys.\nII. No birds are chairs.", "o": ["Both I and II follow", "Only conclusion II follows", "Only conclusion I follows", "Neither I nor II follows"], "a": 3, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी चाबियाँ पक्षी नहीं है।\nकुछ पक्षी कुर्सियाँ हैं।\nनिष्कर्ष:\nI. कोई भी कुर्सियाँ चाबियाँ नहीं है।\nII. कोई भी पक्षी कुर्सियाँ नहीं है।", "oh": ["I और II दोनों सही हैं", "केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है", "न I सही है, न II"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '×', '−' means '÷', '×' means '+', '÷' means '−', then what is the value of the following expression?\n10 × 11 × 17 = ?", "o": ["40", "35", "38", "76"], "a": 2, "e": "Replace the signs: 10 + 11 + 17 = 38 (using BODMAS).", "qh": "अगर '+' का मतलब '×', '−' का मतलब '÷', '×' का मतलब '+', '÷' का मतलब '−' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n10 × 11 × 17 = ?", "oh": ["40", "35", "38", "76"], "eh": "चिह्न बदलें: 10 + 11 + 17 = 38 (BODMAS से)।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n148   671   832   132   423\nIf the digits of each number are written in reverse order, what is the sum of the first and third digits of the second smallest number so formed?", "o": ["2", "3", "4", "6"], "a": 1, "e": "Reversed numbers in order: 176, 231, 238, 324, 841. Second smallest = 231; 2 + 1 = 3.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n148   671   832   132   423\nअगर हर संख्या के अंकों को उलटे क्रम में लिखा जाए, तो बनी हुई दूसरी सबसे छोटी संख्या के पहले और तीसरे अंक का योग क्या होगा?", "oh": ["2", "3", "4", "6"], "eh": "उलटी संख्याएँ क्रम में: 176, 231, 238, 324, 841। दूसरी सबसे छोटी = 231; 2 + 1 = 3।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'milk sun long' is written as 'su ta gu',\n'tree milk is' is written as 'lo su pu',\n'sun city tree' is written as 'lo gu mo',\nWhat is the code for 'milk'?", "o": ["gu", "ta", "lo", "su"], "a": 3, "e": "Compare the sentences: common words and common codes match. This gives 'milk' = 'su'.", "qh": "एक कोड भाषा में:\n'milk sun long' को 'su ta gu' लिखा जाता है,\n'tree milk is' को 'lo su pu' लिखा जाता है,\n'sun city tree' को 'lo gu mo' लिखा जाता है,\n'milk' का कोड क्या है?", "oh": ["gu", "ta", "lo", "su"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'milk' = 'su' मिलता है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "D, H, E, F, M and P are sitting around a circular table, all facing the centre.\nP sits opposite F.\nD is an immediate neighbour of F.\nH is not an immediate neighbour of M.\nM is an immediate neighbour of E.\nE sits second to the left of F.\nWho sits to the immediate right of E?", "o": ["M", "F", "D", "H"], "a": 0, "e": "Only one arrangement fits. Going to the right (anticlockwise) from E: E → M → F → D → H → P. Answer: M.", "qh": "D, H, E, F, M और P एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nP, F के ठीक सामने बैठा है।\nD, F का ठीक पड़ोसी है।\nH, M का ठीक पड़ोसी नहीं है।\nM, E का ठीक पड़ोसी है।\nE, F के बाईं ओर दूसरे स्थान पर बैठा है।\nE के ठीक दाईं ओर कौन बैठा है?", "oh": ["M", "F", "D", "H"], "eh": "केवल एक व्यवस्था बैठती है। E से दाईं ओर (घड़ी की उलटी दिशा में) चलें: E → M → F → D → H → P। उत्तर: M।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Venn Diagram", "q": "In a group of 60 people, 23 like Hindi, 28 like English and 8 like both. How many like only Hindi?", "o": ["20", "15", "23", "37"], "a": 1, "e": "Only Hindi = 23 − 8 = 15.", "qh": "60 लोगों के समूह में 23 को हिंदी पसंद है, 28 को अंग्रेज़ी पसंद है और 8 को दोनों पसंद हैं। कितने लोगों को केवल हिंदी पसंद है?", "oh": ["20", "15", "23", "37"], "eh": "केवल हिंदी = 23 − 8 = 15।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["196", "100", "226", "64"], "a": 2, "e": "All except 226 are perfect squares.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["196", "100", "226", "64"], "eh": "226 को छोड़कर सभी पूर्ण वर्ग हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "V, B, K, F and C are sitting in a row, all facing North.\nV does not sit at either end.\nF and K sit next to each other.\nF sits immediately to the right of V.\nF is not an immediate neighbour of B.\nK is not an immediate neighbour of V.\nB sits immediately to the right of K.\nWho sits exactly in the middle of the row?", "o": ["V", "K", "C", "F"], "a": 3, "e": "Only one order fits all clues (left to right): C V F K B. Answer: F.", "qh": "V, B, K, F और C एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nV किसी भी छोर पर नहीं बैठा है।\nF और K पास-पास बैठे हैं।\nF, V के ठीक दाईं ओर बैठा है।\nF, B का ठीक पड़ोसी नहीं है।\nK, V का ठीक पड़ोसी नहीं है।\nB, K के ठीक दाईं ओर बैठा है।\nपंक्ति के ठीक बीच में कौन बैठा है?", "oh": ["V", "K", "C", "F"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): C V F K B। उत्तर: F।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "'A ÷ B' means 'A is the sister of B'; 'A − B' means 'A is the husband of B'; 'A # B' means 'A is the son of B'; 'A + B' means 'A is the brother of B'. If K + V ÷ A # W, how is K related to W?", "o": ["Nephew", "Father-in-law", "Son", "Brother-in-law"], "a": 2, "e": "Decode: K is the brother of V; V is the sister of A; A is the son of W. So K is the son of W.", "qh": "'A ÷ B' का अर्थ है 'A, B की बहन है'; 'A − B' का अर्थ है 'A, B का पति है'; 'A # B' का अर्थ है 'A, B का बेटा है'; 'A + B' का अर्थ है 'A, B का भाई है'। अगर K + V ÷ A # W, तो K का W से क्या संबंध है?", "oh": ["भतीजा/भांजा", "ससुर", "बेटा", "साला/देवर/जीजा"], "eh": "अर्थ निकालें: K, V का भाई; V, A की बहन; A, W का बेटा। इसलिए K, W का बेटा है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Neha is facing North. Neha turns 180° anticlockwise, then 180° clockwise. Which direction is Neha facing now?", "o": ["East", "West", "North", "South"], "a": 2, "e": "Net turn = 0° (clockwise 0°). From North this gives North.", "qh": "नेहा का मुँह उत्तर की ओर है। नेहा 180° वामावर्त, फिर 180° दक्षिणावर्त घूमता/घूमती है। अब उसका मुँह किस दिशा में है?", "oh": ["पूर्व", "पश्चिम", "उत्तर", "दक्षिण"], "eh": "कुल घुमाव = 0°। उत्तर से यह उत्तर देता है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Monday", "Friday", "Sunday", "March"], "a": 3, "e": "March is a month; the others are days.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["सोमवार", "शुक्रवार", "रविवार", "मार्च"], "eh": "मार्च महीना है; बाकी दिन हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "If every 2nd letter of the English alphabet is written starting from E (i.e. E, G, I, …), which letter will be 6th from the left end of the new sequence?", "o": ["Q", "O", "M", "S"], "a": 1, "e": "Sequence: E G I K M O Q S U W Y. 6th from the left: O.", "qh": "अगर अंग्रेज़ी वर्णमाला का हर दूसरा अक्षर E से शुरू करके लिखा जाए (यानी E, G, I, …), तो नए क्रम में बाएँ छोर से छठा अक्षर कौन-सा होगा?", "oh": ["Q", "O", "M", "S"], "eh": "क्रम: E G I K M O Q S U W Y। बाएँ से छठा: O।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '×', '−' means '+', '×' means '÷', '÷' means '−', then what is the value of the following expression?\n22 − 25 + 25 = ?", "o": ["647", "657", "1294", "644"], "a": 0, "e": "Replace the signs: 22 + 25 × 25 = 647 (using BODMAS).", "qh": "अगर '+' का मतलब '×', '−' का मतलब '+', '×' का मतलब '÷', '÷' का मतलब '−' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n22 − 25 + 25 = ?", "oh": ["647", "657", "1294", "644"], "eh": "चिह्न बदलें: 22 + 25 × 25 = 647 (BODMAS से)।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n11, 15, 20, 26, 33, 41, ?", "o": ["49", "46", "50", "48"], "a": 2, "e": "Rule: Differences are 4, 5, 6, 7, 8, 9 (increase by 1). So ? = 50.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n11, 15, 20, 26, 33, 41, ?", "oh": ["49", "46", "50", "48"], "eh": "नियम: अंतर 4, 5, 6, 7, 8, 9 हैं (हर बार 1 बढ़ता है)। इसलिए ? = 50।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n2 1 3 2 5 4 4 9 8 7 4 7 3 4 5 1 4 8 2 3 5 8 3 4 1\nHow many even digits are there, each of which is immediately preceded by an odd digit AND immediately followed by a digit greater than 5?", "o": ["4", "3", "5", "2"], "a": 1, "e": "Matching groups: 9 8 7, 7 4 7, 1 4 8 → 3.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n2 1 3 2 5 4 4 9 8 7 4 7 3 4 5 1 4 8 2 3 5 8 3 4 1\nऐसे कितने सम अंक हैं, जिनके ठीक पहले विषम अंक हो और ठीक बाद 5 से बड़ा अंक हो?", "oh": ["4", "3", "5", "2"], "eh": "शर्त पूरी करने वाले समूह: 9 8 7, 7 4 7, 1 4 8 → 3।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "T is the father of G. G is the daughter of F. How is T related to F?", "o": ["Husband", "Son-in-law", "Grandson", "Nephew"], "a": 0, "e": "Draw the family tree: T → G: father; G → F: daughter. So T is the husband of F.", "qh": "T, G का पिता है। G, F की बेटी है। T का F से क्या संबंध है?", "oh": ["पति", "दामाद", "पोता/नाती", "भतीजा/भांजा"], "eh": "परिवार का चार्ट बनाएँ: T → G: पिता; G → F: बेटी। इसलिए T, F का पति है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["NRSV", "CGHK", "JNOS", "EIJM"], "a": 2, "e": "In NRSV, CGHK, EIJM the gaps are +4, +1, +3; in JNOS they are +4, +1, +4.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["NRSV", "CGHK", "JNOS", "EIJM"], "eh": "NRSV, CGHK, EIJM में अंतर +4, +1, +3 है; JNOS में +4, +1, +4 है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'ISLAND' is written as 'GQDOVL'. How will 'MOTHER' be written in that language?", "o": ["PRWKHU", "UHLWRP", "UHKWRP", "UHKWRO"], "a": 2, "e": "Rule: the word is reversed and each letter moves +3. Applying it to MOTHER gives UHKWRP.", "qh": "एक कोड भाषा में 'ISLAND' को 'GQDOVL' लिखा जाता है। उसी भाषा में 'MOTHER' को कैसे लिखा जाएगा?", "oh": ["PRWKHU", "UHLWRP", "UHKWRP", "UHKWRO"], "eh": "नियम: शब्द उलटा करके हर अक्षर +3 खिसकता है। MOTHER पर लगाने से UHKWRP मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nLKSO : MMUQ :: ZOES : ?", "o": ["AQGU", "UGQA", "YMCQ", "AQGV"], "a": 0, "e": "Each letter moves +1, +2, +2, +2 in order. ZOES → AQGU.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nLKSO : MMUQ :: ZOES : ?", "oh": ["AQGU", "UGQA", "YMCQ", "AQGV"], "eh": "हर अक्षर क्रम से +1, +2, +2, +2 खिसकता है। ZOES → AQGU।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 51 students, Ajay is 15th from the left. Ajay and Vikas interchange their positions, after which Ajay is 37th from the left. What was Vikas's original position from the right end?", "o": ["17", "15", "13", "14"], "a": 1, "e": "Vikas was originally at Ajay's new place: 37th from left → from right = 51 − 37 + 1 = 15.", "qh": "51 छात्रों की पंक्ति में अजय बाएँ से 15वें स्थान पर है। अजय और विकास अपनी जगह बदलते हैं, जिसके बाद अजय बाएँ से 37वें स्थान पर है। विकास का मूल स्थान दाएँ छोर से क्या था?", "oh": ["17", "15", "13", "14"], "eh": "विकास पहले अजय की नई जगह पर था: बाएँ से 37वाँ → दाएँ से = 51 − 37 + 1 = 15।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n4, 5, 12, 39, ?, 805", "o": ["159", "160", "165", "163"], "a": 1, "e": "Rule: ×1 + 1, ×2 + 2, ×3 + 3, … So ? = 160.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n4, 5, 12, 39, ?, 805", "oh": ["159", "160", "165", "163"], "eh": "नियम: ×1 + 1, ×2 + 2, ×3 + 3, … इसलिए ? = 160।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "If every 3rd letter of the English alphabet is written starting from B (i.e. B, E, H, …), which letter will be 3rd from the right end of the new sequence?", "o": ["W", "Q", "T", "Z"], "a": 2, "e": "Sequence: B E H K N Q T W Z. 3rd from the right: T.", "qh": "अगर अंग्रेज़ी वर्णमाला का हर तीसरा अक्षर B से शुरू करके लिखा जाए (यानी B, E, H, …), तो नए क्रम में दाएँ छोर से तीसरा अक्षर कौन-सा होगा?", "oh": ["W", "Q", "T", "Z"], "eh": "क्रम: B E H K N Q T W Z। दाएँ से तीसरा: T।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n8 : 504 :: 5 : ?", "o": ["121", "120", "25", "125"], "a": 1, "e": "Rule: x → x³ − x. 8 → 504, so 5 → 120.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n8 : 504 :: 5 : ?", "oh": ["121", "120", "25", "125"], "eh": "नियम: x → x³ − x। 8 → 504, इसलिए 5 → 120।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Arjun is facing South-West. Arjun turns 45° clockwise, then 45° clockwise, then 90° anticlockwise. Which direction is Arjun facing now?", "o": ["North-West", "South-East", "North-East", "South-West"], "a": 3, "e": "Net turn = 0° (clockwise 0°). From South-West this gives South-West.", "qh": "अर्जुन का मुँह दक्षिण-पश्चिम की ओर है। अर्जुन 45° दक्षिणावर्त, फिर 45° दक्षिणावर्त, फिर 90° वामावर्त घूमता/घूमती है। अब उसका मुँह किस दिशा में है?", "oh": ["उत्तर-पश्चिम", "दक्षिण-पूर्व", "उत्तर-पूर्व", "दक्षिण-पश्चिम"], "eh": "कुल घुमाव = 0°। दक्षिण-पश्चिम से यह दक्षिण-पश्चिम देता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nSome bricks are not chairs.\nAll chairs are bottles.\nSome bottles are not trees.\nConclusions:\nI. Some chairs are not bottles.\nII. Some chairs are not bricks.", "o": ["Only conclusion I follows", "Neither I nor II follows", "Both I and II follow", "Only conclusion II follows"], "a": 1, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकुछ ईंटें कुर्सियाँ नहीं हैं।\nसभी कुर्सियाँ बोतलें हैं।\nकुछ बोतलें पेड़ नहीं हैं।\nनिष्कर्ष:\nI. कुछ कुर्सियाँ बोतलें नहीं हैं।\nII. कुछ कुर्सियाँ ईंटें नहीं हैं।", "oh": ["केवल निष्कर्ष I सही है", "न I सही है, न II", "I और II दोनों सही हैं", "केवल निष्कर्ष II सही है"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nI49Z, K64X, M81V, O100T, ?", "o": ["Q120R", "Q121R", "Q123R", "Q121S"], "a": 1, "e": "First letter +2; number: consecutive squares; last letter -2. So ? = Q121R.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nI49Z, K64X, M81V, O100T, ?", "oh": ["Q120R", "Q121R", "Q123R", "Q121S"], "eh": "पहला अक्षर +2; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -2। इसलिए ? = Q121R।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nFI, JM, NQ, RU, ?", "o": ["VY", "VZ", "XY", "VA"], "a": 0, "e": "Letter positions move by +4, +4 (for 1st, 2nd letters). So ? = VY.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nFI, JM, NQ, RU, ?", "oh": ["VY", "VZ", "XY", "VA"], "eh": "अक्षरों की स्थिति +4, +4 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = VY।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "If 3 February 2027 was a Wednesday, what day of the week was 27 August 2027?", "o": ["Friday", "Saturday", "Thursday", "Sunday"], "a": 0, "e": "Days from 3 February 2027 to 27 August 2027 = 205. 205 = 7 × 29 + 2 → 2 odd day(s) after Wednesday = Friday.", "qh": "अगर 3 फ़रवरी 2027 को बुधवार था, तो 27 अगस्त 2027 को कौन-सा दिन था?", "oh": ["शुक्रवार", "शनिवार", "गुरुवार", "रविवार"], "eh": "3 फ़रवरी 2027 से 27 अगस्त 2027 तक दिन = 205। 205 = 7 × 29 + 2 → बुधवार के 2 दिन बाद = शुक्रवार।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Data Sufficiency", "q": "Question: What is the present age of Deepak?\nStatement I: Deepak will be 12 years old after 5 years.\nStatement II: Karan is 19 years old.\nWhich of the following is correct?", "o": ["The data in both statements together is not sufficient", "The data in both statements I and II together is needed", "The data in statement II alone is sufficient", "The data in statement I alone is sufficient"], "a": 3, "e": "Statement I alone fixes the age; II alone does not.", "qh": "प्रश्न: दीपक की अभी की आयु क्या है?\nकथन I: 5 साल बाद दीपक की आयु 12 साल होगी।\nकथन II: करण की आयु 19 साल है।\nनीचे दिए विकल्पों में से कौन-सा सही है?", "oh": ["दोनों कथन मिलकर भी काफ़ी नहीं हैं", "दोनों कथन I और II साथ में चाहिए", "केवल कथन II का आँकड़ा काफ़ी है", "केवल कथन I का आँकड़ा काफ़ी है"], "eh": "अकेला कथन I आयु तय कर देता है; अकेला II नहीं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nGrape : Vine :: Apple : ?", "o": ["Fruit", "Seed", "Red", "Tree"], "a": 3, "e": "Relation: 'grows on'. Grape – Vine, so Apple – Tree.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nअंगूर : बेल :: सेब : ?", "oh": ["फल", "बीज", "लाल", "पेड़"], "eh": "संबंध: 'पर उगता है'। अंगूर – बेल, इसलिए सेब – पेड़।", "level": "medium"}]});
